`visibleWindow` calculates the half-open row interval needed to render a fixed-height virtual list. `totalRows`, `rowHeight`, `scrollTop`, `viewportHeight`, and `overscan` must be finite integers. Additionally, `totalRows`, `scrollTop`, `viewportHeight`, and `overscan` must be non-negative, while `rowHeight` must be positive; otherwise throw `RangeError`. Clamp scrolling beyond the content naturally to the range `[0, totalRows]`. Include every row touched even partially by the viewport, then extend both sides by `overscan` without exceeding the list bounds. An empty list returns `{ start: 0, endExclusive: 0 }`. The function must not mutate its input.

Known-bad source:

export interface WindowRequest {
  readonly totalRows: number;
  readonly rowHeight: number;
  readonly scrollTop: number;
  readonly viewportHeight: number;
  readonly overscan: number;
}

export interface RowWindow {
  readonly start: number;
  readonly endExclusive: number;
}

export function visibleWindow(request: WindowRequest): RowWindow {
  const values = [request.totalRows, request.rowHeight, request.scrollTop, request.viewportHeight, request.overscan];
  if (values.some((value) => !Number.isFinite(value) || !Number.isInteger(value))) {
    throw new RangeError("All values must be finite integers");
  }
  if (request.totalRows < 0 || request.rowHeight <= 0 || request.scrollTop < 0 || request.viewportHeight < 0 || request.overscan < 0) {
    throw new RangeError("Invalid window dimensions");
  }
  if (request.totalRows === 0) return { start: 0, endExclusive: 0 };

  const first = Math.min(request.totalRows, Math.floor(request.scrollTop / request.rowHeight));
  const visibleEnd = Math.min(request.totalRows, Math.floor((request.scrollTop + request.viewportHeight) / request.rowHeight));
  return {
    start: Math.max(0, first - request.overscan),
    endExclusive: Math.min(request.totalRows, visibleEnd + request.overscan),
  };
}

