import { visibleWindow, WindowRequest } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

function throwsRangeError(fn: () => void, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

deepEqual(visibleWindow({ totalRows: 0, rowHeight: 10, scrollTop: 0, viewportHeight: 100, overscan: 5 }), { start: 0, endExclusive: 0 }, 'empty list has empty window');
deepEqual(visibleWindow({ totalRows: 20, rowHeight: 10, scrollTop: 15, viewportHeight: 20, overscan: 0 }), { start: 1, endExclusive: 4 }, 'includes partially touched rows');
deepEqual(visibleWindow({ totalRows: 20, rowHeight: 10, scrollTop: 20, viewportHeight: 20, overscan: 2 }), { start: 0, endExclusive: 6 }, 'extends both sides by overscan');
deepEqual(visibleWindow({ totalRows: 5, rowHeight: 10, scrollTop: 35, viewportHeight: 30, overscan: 3 }), { start: 0, endExclusive: 5 }, 'clamps viewport and overscan at bounds');
deepEqual(visibleWindow({ totalRows: 5, rowHeight: 10, scrollTop: 1000, viewportHeight: 20, overscan: 1 }), { start: 4, endExclusive: 5 }, 'clamps scrolling beyond content');
deepEqual(visibleWindow({ totalRows: 5, rowHeight: 10, scrollTop: 0, viewportHeight: 50, overscan: 0 }), { start: 0, endExclusive: 5 }, 'renders the full exact-height viewport');

const request: WindowRequest = Object.freeze({ totalRows: 10, rowHeight: 8, scrollTop: 9, viewportHeight: 8, overscan: 1 });
const before = JSON.stringify(request);
deepEqual(visibleWindow(request), { start: 0, endExclusive: 4 }, 'handles partial rows with overscan');
assert(JSON.stringify(request) === before, 'does not mutate request');

const invalid: WindowRequest[] = [
  { totalRows: -1, rowHeight: 1, scrollTop: 0, viewportHeight: 0, overscan: 0 },
  { totalRows: 1, rowHeight: 0, scrollTop: 0, viewportHeight: 0, overscan: 0 },
  { totalRows: 1, rowHeight: -1, scrollTop: 0, viewportHeight: 0, overscan: 0 },
  { totalRows: 1, rowHeight: 1, scrollTop: -1, viewportHeight: 0, overscan: 0 },
  { totalRows: 1, rowHeight: 1, scrollTop: 0, viewportHeight: -1, overscan: 0 },
  { totalRows: 1, rowHeight: 1, scrollTop: 0, viewportHeight: 0, overscan: -1 },
  { totalRows: 1.5, rowHeight: 1, scrollTop: 0, viewportHeight: 0, overscan: 0 },
  { totalRows: 1, rowHeight: Number.NaN, scrollTop: 0, viewportHeight: 0, overscan: 0 },
  { totalRows: 1, rowHeight: 1, scrollTop: Number.POSITIVE_INFINITY, viewportHeight: 0, overscan: 0 }
];
for (const value of invalid) {
  throwsRangeError(() => visibleWindow(value), `rejects invalid request ${JSON.stringify(value)}`);
}

